#!/usr/bin/env node
// Render a captured conversation JSONL into a compact readable transcript.
// usage: node render.mjs <file> [maxTextChars]
import { readFileSync } from 'node:fs';
const file = process.argv[2];
const MAX = Number(process.argv[3] || 1400);
const lines = readFileSync(file, 'utf8').split('\n').filter(Boolean);
const clip = (s, n = MAX) => {
  s = String(s ?? '').replace(/\s+\n/g, '\n');
  return s.length > n ? s.slice(0, n) + `\n…[+${s.length - n} chars]` : s;
};
let prevTs = null;
for (const line of lines) {
  let e;
  try { e = JSON.parse(line); } catch { continue; }
  const ts = e.timestamp ? new Date(e.timestamp) : null;
  let gap = '';
  if (ts && prevTs) {
    const d = (ts - prevTs) / 1000;
    if (d >= 20) gap = ` [+${d.toFixed(0)}s]`;
  }
  if (ts) prevTs = ts;
  const stamp = e.timestamp ? e.timestamp.slice(11, 19) : '--------';
  const msg = e.message;
  if (!msg) { continue; }
  const role = msg.role;
  const content = msg.content;
  if (typeof content === 'string') {
    console.log(`\n[${stamp}${gap}] ${role.toUpperCase()}: ${clip(content)}`);
    continue;
  }
  if (!Array.isArray(content)) continue;
  for (const c of content) {
    if (c.type === 'text') {
      if (!c.text?.trim()) continue;
      console.log(`\n[${stamp}${gap}] ${role.toUpperCase()}: ${clip(c.text)}`);
    } else if (c.type === 'thinking') {
      console.log(`\n[${stamp}${gap}] (thinking): ${clip(c.thinking, 700)}`);
    } else if (c.type === 'tool_use') {
      const inp = JSON.stringify(c.input);
      console.log(`\n[${stamp}${gap}] TOOL ${c.name}: ${clip(inp, 700)}`);
    } else if (c.type === 'tool_result') {
      let t = c.content;
      if (Array.isArray(t)) t = t.map(x => x.text ?? `<${x.type}>`).join('\n');
      console.log(`[${stamp}${gap}]   -> ${c.is_error ? 'ERROR ' : ''}${clip(t, 500)}`);
    }
  }
}
